    16	// DispatchStaleReminders implements the project-owned lead.dispatch_stale_reminders Handler.
    17	func DispatchStaleReminders(ctx context.Context, caps capabilities.DispatchStaleRemindersCapabilities, input capabilities.DispatchStaleRemindersInput) (capabilities.DispatchStaleRemindersOutput, error) {
    18		if input.ScheduledAt.IsZero() {
    19			return capabilities.DispatchStaleRemindersOutput{}, dispatchStaleRemindersError("invalid_input", "scheduled_at is required")
    20		}
    21		if input.ScheduledAt.Weekday() == time.Saturday || input.ScheduledAt.Weekday() == time.Sunday {
    22			return capabilities.DispatchStaleRemindersOutput{}, dispatchStaleRemindersError("invalid_schedule", "stale reminders run only on weekdays")
    23		}
    24		if caps.Execution == nil || caps.Lead == nil || caps.LeadReminderReceipt == nil || caps.Notifications == nil {
    25			return capabilities.DispatchStaleRemindersOutput{}, dispatchStaleRemindersError("capability_unavailable", "required Action capability is unavailable")
    26		}
    27		principal := caps.Execution.Principal()
    28		if !principal.Known || principal.RoleKey != "crm_scheduler" {
    29			return capabilities.DispatchStaleRemindersOutput{}, dispatchStaleRemindersError("principal_invalid", "a known CRM scheduler principal is required")
    30		}
    31	
    32		cutoff := input.ScheduledAt.Add(-7 * 24 * time.Hour)
    33		leads, err := caps.Lead.List(ctx, data.NewLeadQuery().
    34			WhereStatusEqual(schema.LeadStatusContacted).
    35			WhereStatusChangedAtLessThan(cutoff).
    36			OrderByIDAscending().
    37			Page(1, 200))
    38		if err != nil {
    39			return capabilities.DispatchStaleRemindersOutput{}, err
    40		}
    41		if len(leads) > staleReminderBatchSize {
    42			return capabilities.DispatchStaleRemindersOutput{}, dispatchStaleRemindersError("unbounded_result", "lead query exceeded the authorized batch size")
    43		}
    44	
    45		location := input.ScheduledAt.Location()
    46		businessDate := time.Date(input.ScheduledAt.Year(), input.ScheduledAt.Month(), input.ScheduledAt.Day(), 0, 0, 0, 0, location)
    47		output := capabilities.DispatchStaleRemindersOutput{EligibleCount: int64(len(leads))}
    48		for leadIndex := 0; leadIndex < staleReminderBatchSize; leadIndex++ {
    49			if leadIndex >= len(leads) {
    50				break
    51			}
    52			lead := leads[leadIndex]
    53			if lead.ID == "" || lead.UpdatedAt == "" || lead.OwnerID == "" || lead.CompanyName == "" || lead.Status != schema.LeadStatusContacted || lead.StatusChangedAt == nil || !lead.StatusChangedAt.Before(cutoff) {
    54				return capabilities.DispatchStaleRemindersOutput{}, dispatchStaleRemindersError("candidate_invalid", "lead query returned an ineligible or incomplete candidate")
    55			}
    56	
    57			dedupeKey := fmt.Sprintf("lead:%s:stale-contact:%s", lead.ID, businessDate.Format("2006-01-02"))
    58			exists, err := caps.LeadReminderReceipt.Exists(ctx, data.NewLeadReminderReceiptQuery().WhereDedupeKeyEqual(dedupeKey))
    59			if err != nil {
    60				return capabilities.DispatchStaleRemindersOutput{}, err
    61			}
    62			if exists {
    63				continue
    64			}
    65	
    66			receipt, err := caps.LeadReminderReceipt.Create(ctx, schema.CreateLeadReminderReceipt{
    67				BusinessDate: businessDate,
    68				DedupeKey:    dedupeKey,
    69				LeadID:       schema.NewLeadReminderReceiptLeadIDReference(lead.ID),
    70				RecipientID:  lead.OwnerID,
    71				Status:       schema.LeadReminderReceiptStatusDispatched,
    72			})
    73			if err != nil {
    74				return capabilities.DispatchStaleRemindersOutput{}, err
    75			}
    76			if receipt.ID == "" {
    77				return capabilities.DispatchStaleRemindersOutput{}, dispatchStaleRemindersError("mutation_invalid", "reminder receipt creation returned no identity")
    78			}
    79	
    80			companyName := lead.CompanyName
    81			sourceEventID := principal.RequestID
    82			if sourceEventID == "" {
    83				sourceEventID = dedupeKey
    84			}
    85			_, err = caps.Notifications.Dispatch(ctx, capabilities.DispatchStaleRemindersNotificationIntent{
    86				EventType:        "crm.stale_contact_reminder",
    87				SourceEventID:    sourceEventID,
    88				RecipientUserIDs: []string{lead.OwnerID},
    89				Surface:          approveConversionSurface,
    90				SubjectObjectKey: "lead",
    91				SubjectRecordID:  string(lead.ID),
    92				SubjectVersion:   lead.UpdatedAt,
    93				DedupeKey:        dedupeKey,
    94				GroupKey:         "lead:" + string(lead.ID),
    95				Alert:            true,
    96				OccurredAt:       input.ScheduledAt,
    97				Variables: []capabilities.DispatchStaleRemindersNotificationVariable{
    98					{Key: "company_name", StringValue: &companyName},
    99				},
   100			})
   101			if err != nil {
   102				return capabilities.DispatchStaleRemindersOutput{}, err
   103			}
   104			output.DispatchedCount++
   105		}
   106	
   107		return output, nil
   108	}
