def validate_session_id(value: str, source: str) -> str:
    candidate = value.strip()
    if not SAFE_SESSION_ID.fullmatch(candidate):
        raise ValueError(f"unsafe development session ID from {source}")
    return candidate


def default_domainry_log() -> Path:
    explicit = os.environ.get("DOMAINRY_LOG_PATH", "").strip()
    if explicit:
        return Path(explicit).expanduser()
    candidates = (
        Path.home() / "Library" / "Logs" / "Domainry" / "domainry.log",
        Path.home() / ".local" / "state" / "domainry" / "domainry.log",
    )
    for candidate in candidates:
        if candidate.is_file():
            return candidate
    return candidates[0] if sys.platform == "darwin" else candidates[1]


def session_from_domainry_log(project: Path, log_path: Path) -> str:
    if log_path.is_symlink() or not log_path.is_file():
        raise ValueError(f"Domainry session log is unavailable: {log_path}")
    active_by_project: dict[str, str] = {}
    with log_path.open("r", encoding="utf-8", errors="replace") as source:
        for line in source:
            try:
                message = str(json.loads(line).get("message", ""))
            except json.JSONDecodeError:
                continue
            created = CREATE_PATTERN.search(message)
            if created:
                session_id = validate_session_id(created.group(1), "Domainry log")
                try:
                    cwd = str(Path(created.group(2)).expanduser().resolve(strict=False))
                except OSError:
                    continue
                active_by_project[session_id] = cwd
            detached = DETACH_PATTERN.search(message)
            if detached:
                active_by_project.pop(detached.group(1), None)
    matches = sorted(
        session_id for session_id, cwd in active_by_project.items()
        if cwd == str(project)
    )
    if len(matches) != 1:
        raise ValueError(
            "Domainry log must contain exactly one active session for project "
            f"{project}; observed {len(matches)}"
        )
    return matches[0]


def resolve_session_id(explicit: str, project: Path, log_path: Path) -> tuple[str, str]:
    if explicit.strip():
        return validate_session_id(explicit, "argument"), "argument"
    for key in SESSION_ENVIRONMENT_KEYS:
        value = os.environ.get(key, "").strip()
        if value:
            return validate_session_id(value, f"environment:{key}"), f"environment:{key}"
    return session_from_domainry_log(project, log_path), f"domainry_log:{log_path}"


def initialize_continuation(
    project: Path, skill_root: Path, cli: Path, session_id: str, focused_packages: list[str],
) -> dict[str, object]:
    gates = skill_root / "bin" / "domainry-development-gates.py"
    if gates.is_symlink() or not gates.is_file():
        raise ValueError(f"development Gate runner is unavailable: {gates}")
    command = [
        sys.executable, str(gates), "--project", str(project), "--session-id", session_id,
        "init-continuation", "--cli", str(cli),
    ]
    for package in focused_packages:
        command.extend(("--focused-test-package", package))
    try:
        completed = subprocess.run(command, capture_output=True, text=True, check=False, timeout=60)
    except subprocess.TimeoutExpired as error:
        raise ValueError("continuation profile initialization timed out") from error
    if completed.returncode != 0:
        message = completed.stderr.strip()
        try:
            message = json.loads(message).get("message", message)
        except json.JSONDecodeError:
            pass
        raise ValueError(f"continuation profile initialization failed: {message}")
    try:
        document = json.loads(completed.stdout)
    except json.JSONDecodeError as error:
        raise ValueError("continuation profile returned invalid JSON") from error
    if (
        not isinstance(document, dict)
        or document.get("contract_version") != CONTINUATION_INIT_VERSION
        or document.get("profile") != CONTINUATION_PROFILE
        or document.get("project") != str(project)
        or document.get("session_id") != session_id
    ):
        raise ValueError("continuation profile contract differs")
    return document


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(
        description=(
            "Resolve the embedded CLI and the current development-session identity. "
            "The session ID is taken from --session-id when given, then from the "
            "environment (" + ", ".join(SESSION_ENVIRONMENT_KEYS) + "), then from the "
            "Domainry session log."
        )
    )
    parser.add_argument("--project", required=True, type=Path, help="Project root directory")
    parser.add_argument(
        "--session-id",
        default="",
        help="Explicit development session ID; overrides environment and log discovery",
    )
    parser.add_argument(
        "--domainry-log",
        type=Path,
        help=(
            "Domainry session log path; defaults to $DOMAINRY_LOG_PATH, then "
            "~/Library/Logs/Domainry/domainry.log (macOS) or "
            "~/.local/state/domainry/domainry.log (Linux)"
        ),
    )
    parser.add_argument(
        "--profile",
        choices=(CONTINUATION_PROFILE,),
        help="Explicit compact continuation profile; omitted for the normal whole-project workflow",
    )
    parser.add_argument(
        "--focused-test-package",
        action="append",
        default=[],
        help="Project-relative Go package for the compact continuation's focused test Gate",
    )
    args = parser.parse_args(argv)

    project_candidate = args.project.expanduser()
    if project_candidate.is_symlink():
        raise ValueError("project root must not be a symlink")
    project = project_candidate.resolve(strict=True)
    if not project.is_dir():
        raise ValueError(f"project root is not a directory: {project}")
